jQuery(document).ready(function($){
	
var affwp_ref = $.cookie("affwp_ref");
if (affwp_ref != null) {
    console.log(affwp_ref);
	var check_query_param = new URL(location.href).searchParams.get('ref');
	if (check_query_param != null) {
		console.log("URL already has ref param");
		return false;
	}
	else {
// Construct URLSearchParams object instance from current URL querystring.
var queryParams = new URLSearchParams(window.location.search);
 
// Set new or modify existing parameter value. 
queryParams.set('ref', affwp_ref);
 
// Replace current querystring with the new one.
history.replaceState(null, null, "?"+queryParams.toString());
	}
}
else {
    return false;
}

});